_____4FEE_70BC.name = "修炼"
function _____4FEE_70BC.prototype.____constructor(self)
    --- 第一层：2000金币    全属性+50    杀敌金币+2    3分钟后获得1W金币
    -- 第二层：2W金币    全属性强化+10%    杀敌时有50%概率获得1额外经验    魔抗+20%（BOSS技能减伤）
    -- 第三层：4W金币    杀敌金币+5    全属性+500    魔抗+30%
    -- 8W    死亡后立刻复活机会+3    攻击强化+30%    存档掉率+5%（加算）
    -- 10W    力量强化+30%    敏捷强化+30%    智力强化+30%
    -- 20W    伤害强化+50%    当前护甲翻倍    存档掉率+5%（加算）
    -- 40W    当前力量+20%    当前敏捷+20%    当前智力+20%
    -- 80W    当前力量+30%    当前敏捷+30%    当前智力+30%
    -- 100W    当前力量+50%    当前敏捷+50%    当前智力+50%
    local actorType = ActorTypeUtil:getActorType("修炼")
    if settings.gameDifficulty < 2 and settings.gameMode == MapModel["模式1_普通模式"] then
        local actorAbilityType = ActorTypeShopUtil:warpActorItem2SellingAbility(actorType.id)
        actorAbilityType.disable = true
        actorAbilityType.requiredTip = "难2"
    end
    local as = ActorTypeShopUtil:warpActorItem2SellingAbility(actorType.id)
    as.tooltipLabel1 = "2000"
    as.onCreated = function(____, actor)
        actor:set("tooltipLabel1", nil)
    end
    actorType.onBuy = function(____, actor, buyingUnit)
        ____exports.default["三选一"](____exports.default, actor, buyingUnit)
    end
end
_____4FEE_70BC["三选一"] = function(self, actor, buyingUnit)
    local player = GetOwningPlayer(buyingUnit)
    if not IsHandle(player) then
        return
    end
    local pid = GetPlayerId(player)
    local unit = PlayerUtil:getHero(player)
    if unit == nil then
        return
    end
    actor:destroy()
    local pData = DataBase:getPlayerSolarData(player, true)
    local needGold = 2000
    if pData["修炼次数"] ~= nil and pData["修炼次数"] > 0 then
        needGold = 20000 * 2 ^ (pData["修炼次数"] - 1)
    end
    needGold = math.min(needGold, 1000000)
    if not PlayerUtil:costEnoughState(player, needGold) then
        MouseFrameUtil:showTipText(
            "|cffff0000金币不足!需要:" .. tostring(needGold),
            1,
            player
        )
        return
    end
    pData["修炼次数"] = (pData["修炼次数"] or 0) + 1
    AsyncUtil:run(
        function()
            local nextText = math.min(20000 * 2 ^ (pData["修炼次数"] - 1), 1000000)
            ActorTypeShopUtil:warpActorItem2SellingAbility("修炼").tooltipLabel1 = TextUtil:toCnUnit(nextText)
        end,
        player
    )
    local level = pData["修炼次数"]
    local hero = unit
    local attribute = AttributeUtil:getPlayerAttribute(
        GetOwningPlayer(hero),
        true
    )
    if level == 1 then
        DialogUtil:show(
            pid,
            "修炼LV" .. tostring(level),
            function(____, index, text)
                if index == 0 then
                    HeroUtil:addHeroProperty(hero, 50)
                elseif index == 1 then
                    attribute.add_gold_on_kill = (attribute.add_gold_on_kill or 0) + 2
                elseif index == 2 then
                    BaseUtil.runLater(
                        180,
                        function()
                            PlayerUtil:message("修炼：获得1W金币!", 5, player)
                            PlayerUtil:addGoldState(player, 10000)
                        end
                    )
                end
            end,
            "全属性+50",
            "杀敌金币+2",
            "3分钟后获得1W金币"
        )
    elseif level == 2 then
        DialogUtil:show(
            pid,
            "修炼LV" .. tostring(level),
            function(____, index, text)
                if index == 0 then
                    attribute.full_property_p = (attribute.full_property_p or 0) + 0.1
                elseif index == 1 then
                    attribute["经验倍率"] = (attribute["经验倍率"] or 0) + 1
                elseif index == 2 then
                    attribute.magic_damage_reduction = (attribute.magic_damage_reduction or 0) + 0.2
                end
            end,
            "全属性强化+10% ",
            "经验倍率x2",
            "魔抗+20%（BOSS技能减伤）"
        )
    elseif level == 3 then
        DialogUtil:show(
            pid,
            "修炼LV" .. tostring(level),
            function(____, index, text)
                if index == 0 then
                    attribute.add_gold_on_kill = (attribute.add_gold_on_kill or 0) + 5
                elseif index == 1 then
                    HeroUtil:addHeroProperty(hero, 500)
                elseif index == 2 then
                    attribute.magic_damage_reduction = (attribute.magic_damage_reduction or 0) + 0.3
                end
            end,
            "杀敌金币+5 ",
            "全属性+500",
            "魔抗+30%"
        )
    elseif level == 4 then
        DialogUtil:show(
