                elseif index == 1 then
                    attribute.attack_p = (attribute.attack_p or 0) + 0.3
                elseif index == 2 then
                    attribute["存档掉率"] = (attribute["存档掉率"] or 0) + 0.05
                end
            end,
            "死亡后立刻复活机会+3",
            "攻击强化+30%",
            "存档掉率+5%（加算）"
        )
    elseif level == 5 then
        DialogUtil:show(
            pid,
            "修炼LV" .. tostring(level),
            function(____, index, text)
                if index == 0 then
                    attribute.strength_p = (attribute.strength_p or 0) + 0.3
                elseif index == 1 then
                    attribute.agility_p = (attribute.agility_p or 0) + 0.3
                elseif index == 2 then
                    attribute.intelligence_p = (attribute.intelligence_p or 0) + 0.3
                end
            end,
            "力量增幅+30%",
